<?php
declare(strict_types=1);
namespace App\Services\Fiscal;
use App\Models\Fiscal\Sale_fiscal_pricing_preparations_model;
use App\Models\Invoices_model;
use RuntimeException;
class SaleTaxAdjustmentService{
 private $db;private FiscalDecimalCalculator$d;
 public function __construct($db=null){$this->db=$db?:db_connect();$this->d=new FiscalDecimalCalculator();}
 public function confirmAndApply(int$preparationId,int$userId,bool$confirmed):array{if(!$confirmed)throw new RuntimeException('Debes confirmar que se actualizará el total y el saldo de la venta.');$this->db->transBegin();try{$table=$this->db->prefixTable('sale_fiscal_pricing_preparations');$p=$this->db->query("SELECT * FROM {$table} WHERE id=? FOR UPDATE",[$preparationId])->getRow();if(!$p||$p->status==='applied'||$p->applied_to_sale)throw new RuntimeException('La preparación ya fue aplicada o no existe.');if($p->pricing_mode!=='tax_exclusive'||!(int)$p->requires_confirmation)throw new RuntimeException('Esta preparación no requiere ajustar la venta.');$invoice=$this->db->query('SELECT * FROM '.$this->db->prefixTable('invoices').' WHERE id=? FOR UPDATE',[$p->invoice_id])->getRow();if(!$invoice||$invoice->deleted||$invoice->status==='cancelled')throw new RuntimeException('La venta no está disponible.');$paid=(string)($this->db->table('invoice_payments')->selectSum('amount','total')->where(['invoice_id'=>$p->invoice_id,'deleted'=>0])->get()->getRow()->total??'0');if($this->d->compare((string)$invoice->invoice_total,(string)$p->administrative_total)!==0||$this->d->compare($paid,(string)$p->payment_total_snapshot)!==0)throw new RuntimeException('La venta cambió después de la revisión. Actualiza la simulación antes de aplicar impuestos.');$payload=json_decode((string)$p->calculation_payload,true);if(!($payload['rise_mapping_supported']??false))throw new RuntimeException('La combinación fiscal no puede representarse de forma segura en la estructura actual de RISE.');$taxIds=array_values(array_map('intval',$payload['rise_tax_ids']??[]));if(count($taxIds)>3)throw new RuntimeException('RISE no puede representar esta combinación de impuestos en una venta administrativa.');$invoiceData=['tax_id'=>$taxIds[0]??0,'tax_id2'=>$taxIds[1]??0,'tax_id3'=>$taxIds[2]??0];$this->db->table('invoices')->where('id',$p->invoice_id)->update($invoiceData);$this->db->table('invoice_items')->where(['invoice_id'=>$p->invoice_id,'deleted'=>0])->update(['taxable'=>1]);(new Invoices_model())->update_invoice_total_meta((int)$p->invoice_id);$updated=$this->db->table('invoices')->where('id',$p->invoice_id)->get()->getRow();if($this->d->compare((string)$updated->invoice_total,(string)$p->estimated_fiscal_total)!==0)throw new RuntimeException('El cálculo oficial de RISE no coincide con la simulación; no se aplicó el ajuste.');$this->db->table('sale_fiscal_pricing_preparations')->where('id',$preparationId)->update(['status'=>'applied','requires_confirmation'=>0,'confirmed_by'=>$userId,'confirmed_at'=>get_current_utc_time(),'applied_to_sale'=>1,'applied_by'=>$userId,'applied_at'=>get_current_utc_time(),'updated_at'=>get_current_utc_time()]);if(!$this->db->transStatus())throw new RuntimeException('No fue posible aplicar el ajuste.');$this->db->transCommit();return['preparation_id'=>$preparationId,'invoice_id'=>(int)$p->invoice_id,'previous_total'=>(string)$p->administrative_total,'new_total'=>(string)$updated->invoice_total,'new_balance'=>$this->d->money($this->d->sub((string)$updated->invoice_total,$paid))];}catch(\Throwable$e){$this->db->transRollback();throw$e;}}
}
